/** A guide by id, falling back to the generic one rather than to nothing. */
export function guideFor(id) {
  return (
    NAMESERVER_GUIDES.find(guide => guide.id === id) ||
    NAMESERVER_GUIDES[NAMESERVER_GUIDES.length - 1]
  )
}
