import * as React from "react"
import { adminCall } from "./admin-call"
import * as s from "./AccountActions.module.css"

/**
 * Account actions — FCS-098.
 * ============================================================================
 * Two buttons, two questions:
 *
 *   Run all pipelines       "how far does each one get?" Each pipeline runs
 *                           its real read-only steps in order and stops where
 *                           the live one would.
 *   Health-check each       "what is wrong, and where?" Every step and every
 *                           service underneath is checked, whatever failed
 *                           before it.
 *
 * Neither buys, writes or changes anything: see functions/admin-actions. The
 * screen says so before it is pressed, and says what it found in the words of
 * the step, not as an error code.
 *
 * ── NOT BUILT IS NOT "FINE" ────────────────────────────────────────────────
 * A step that does not exist yet is shown in its own colour with its own
 * count. A report that folded those into the passes would look healthier than
 * the product is.
 */

const WORDS = {
  pass: "Pass",
  fail: "Fail",
  notbuilt: "Not built",
  skipped: "Not run",
  notreached: "Not reached",
}

const SUMMARY_ORDER = ["pass", "fail", "notbuilt", "skipped", "notreached"]

const when = value => {
  const d = new Date(value)
  return Number.isNaN(d.getTime()) ? "" : d.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit", second: "2-digit" })
}

const StepList = ({ steps, label }) => (
  <ol className={s.steps} aria-label={label}>
    {steps.map((step, i) => (
      <li key={step.id} className={s.step} data-status={step.status} data-step={step.id}>
        <span className={s.mark} aria-hidden="true">
          {step.status === "pass" ? "✓" : step.status === "fail" ? "✕" : i + 1}
        </span>
        <span className={s.stepText}>
          <span className={s.stepName}>
            {step.label}
            {step.writes ? <span className={s.writes}>writes</span> : null}
          </span>
          <span className={s.stepDetail}>{step.detail}</span>
        </span>
        <span className={s.badge} data-status={step.status}>
          {WORDS[step.status] || step.status}
        </span>
        <span className={s.ms}>{step.ms ? `${step.ms} ms` : ""}</span>
      </li>
    ))}
  </ol>
)

const AccountActions = () => {
  const [running, setRunning] = React.useState("")
  const [report, setReport] = React.useState(null)
  const [error, setError] = React.useState("")

  const run = async action => {
    setRunning(action)
    setError("")
    const res = await adminCall("admin-actions", { action })
    setRunning("")
    if (res.status === 401) return setError("Log in with an administrator account to run these.")
    if (res.status === 403) return setError("This account is not an administrator, so these are not available here.")
    if (!res.ok) return setError(res.body.message || `That did not run (HTTP ${res.status}).`)
    setReport(res.body)
  }

  return (
    <div data-testid="account-actions">
      <h2 className={s.title}>Account actions</h2>
      <p className={s.help}>
        Run the domain pipelines against the real services and see how far they get, or check
        every step and service for what is wrong. Nothing is bought, written or changed: the
        steps that would are reported as “not run”.
      </p>

      <div className={s.buttons}>
        <button type="button" className={s.primary} onClick={() => run("run-all")} disabled={Boolean(running)}>
          {running === "run-all" ? "Running…" : "Run all pipelines"}
        </button>
        <button type="button" className={s.secondary} onClick={() => run("health")} disabled={Boolean(running)}>
          {running === "health" ? "Checking…" : "Health-check each pipeline"}
        </button>
      </div>

      {running ? (
        <p className={s.note} role="status">
          Making real, read-only calls to the registrar, Cloudflare and Stripe. This takes a few seconds.
        </p>
      ) : null}
      {error ? <p className={s.error}>{error}</p> : null}

      {report ? (
        <div className={s.report} data-mode={report.mode}>
          <p className={s.when}>
            {report.mode === "run-all" ? "Ran all pipelines" : "Health check"} at {when(report.ranAt)} ·{" "}
            {(report.durationMs / 1000).toFixed(1)}s
          </p>
          <ul className={s.summary} aria-label="Summary">
            {SUMMARY_ORDER.filter(k => report.summary[k] > 0 || k === "pass" || k === "fail").map(k => (
              <li key={k} className={s.chip} data-status={k}>
                <strong>{report.summary[k]}</strong> {WORDS[k].toLowerCase()}
              </li>
            ))}
          </ul>

          {report.pipelines.map(p => (
            <section key={p.id} className={s.pipeline} data-pipeline={p.id}>
              <h3 className={s.pipelineName}>{p.name}</h3>
              <StepList steps={p.steps} label={p.name} />
            </section>
          ))}

          {report.services?.length ? (
            <section className={s.pipeline} data-pipeline="services">
              <h3 className={s.pipelineName}>Services underneath</h3>
              <StepList steps={report.services} label="Services" />
            </section>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}

export default AccountActions
