import * as React from "react"
import { PLAN_CHOICES, getSandbox, setSandbox, useSandbox, useTestMode } from "../../lib/test-mode"
import { adminCall } from "./admin-call"
import TestModeToggle from "./TestModeToggle"
import * as s from "./Permissions.module.css"

/**
 * Change somebody's role — FCS-097.
 * ============================================================================
 * Find a person by email, pick the plan they should be on. Whether that is a
 * pretend or a real change is decided by the same TEST MODE switch the users
 * screen has, shown here too, and with the same rules: on, it writes the
 * administrator's sandbox and nothing is sent; off, it changes the real
 * account after a second, explicit click.
 *
 * "Role" here is the plan: Free, Premium, Lead Generation. Affiliate and Admin
 * are separate things a person can also be, and are deliberately not
 * changeable from a drop-down on a settings page.
 */

const planLabel = id => PLAN_CHOICES.find(p => p.id === id)?.label || id

const RoleChanger = () => {
  const testMode = useTestMode()
  const [users, setUsers] = React.useState(null)
  const [denied, setDenied] = React.useState("")
  const [query, setQuery] = React.useState("")
  const [picked, setPicked] = React.useState(null)
  const [plan, setPlan] = React.useState("free")
  const [confirm, setConfirm] = React.useState(false)
  const [busy, setBusy] = React.useState(false)
  const [message, setMessage] = React.useState({ kind: "", text: "" })
  const sandbox = useSandbox(picked?.id)

  React.useEffect(() => {
    let alive = true
    adminCall("admin-users", { action: "list" }).then(res => {
      if (!alive) return
      if (res.status === 401) return setDenied("Log in with an administrator account to change roles.")
      if (res.status === 403) return setDenied("This account is not an administrator, so roles are not shown here.")
      if (!res.ok) return setDenied(res.body.message || "The users did not load.")
      setUsers(res.body.users || [])
    })
    return () => {
      alive = false
    }
  }, [])

  const matches = React.useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!users || q.length < 2) return []
    return users
      .filter(u => u.email.toLowerCase().includes(q) || (u.name || "").toLowerCase().includes(q))
      .slice(0, 8)
  }, [users, query])

  if (denied) return <p className={s.note}>{denied}</p>
  if (testMode === null) return null

  const pick = user => {
    setPicked(user)
    setPlan(testMode ? getSandbox(user.id).plan || user.plan : user.plan)
    setQuery("")
    setConfirm(false)
    setMessage({ kind: "", text: "" })
  }
  const apply = async () => {
    setMessage({ kind: "", text: "" })
    if (testMode) {
      setSandbox(picked.id, { plan: plan === picked.plan ? undefined : plan })
      return setMessage({
        kind: "ok",
        text:
          plan === picked.plan
            ? `Sandbox cleared: ${picked.email} appears on their real plan.`
            : `Sandbox: ${picked.email} now appears on ${planLabel(plan)}. Their real plan is unchanged.`,
      })
    }
    if (plan === picked.plan) return setMessage({ kind: "warn", text: `They are already on ${planLabel(plan)}.` })
    if (!confirm) return setConfirm(true)
    setBusy(true)
    const res = await adminCall("admin-users", { action: "set-plan", id: picked.id, plan })
    setBusy(false)
    setConfirm(false)
    if (!res.ok) return setMessage({ kind: "error", text: res.body.message || "That did not save." })
    setPicked({ ...picked, plan, planName: planLabel(plan) })
    setUsers(list => list.map(u => (u.id === picked.id ? { ...u, plan, planName: planLabel(plan) } : u)))
    setMessage({
      kind: "ok",
      text: `Saved. ${picked.email} is now on ${planLabel(plan)}.${res.body.stripeNote ? ` ${res.body.stripeNote}` : ""}`,
    })
  }

  return (
    <div data-testid="role-changer">
      <h2 className={s.sectionTitle}>Change a user’s role</h2>
      <p className={s.help}>
        Move somebody between Free, Premium and Lead Generation. With test mode on this only
        changes what you see when you view their account; turn it off to change the real thing.
      </p>

      <TestModeToggle />

      {!picked ? (
        <>
          <input
            className={`${s.input} ${s.grow}`}
            style={{ width: "100%" }}
            type="search"
            value={query}
            onChange={e => setQuery(e.target.value)}
            placeholder={users ? "Search by email or name (two letters or more)" : "Loading the users…"}
            aria-label="Find a user"
            disabled={!users}
            autoComplete="off"
          />
          {matches.length > 0 ? (
            <ul className={s.matches} aria-label="Matching users">
              {matches.map(u => (
                <li key={u.id}>
                  <button type="button" className={s.match} onClick={() => pick(u)}>
                    <span>{u.email}</span>
                    <span className={s.matchPlan}>{u.planName}</span>
                  </button>
                </li>
              ))}
            </ul>
          ) : null}
          {users && query.trim().length >= 2 && matches.length === 0 ? (
            <p className={s.note}>Nobody matches that.</p>
          ) : null}
        </>
      ) : (
        <section className={s.section}>
          <p className={s.facts}>
            <strong>{picked.email}</strong> · real plan: <strong>{planLabel(picked.plan)}</strong>
            {sandbox.plan ? <span className={s.pill}>Sandbox: {planLabel(sandbox.plan)}</span> : null}
          </p>
          <div className={s.row}>
            <select
              className={s.input}
              value={plan}
              onChange={e => {
                setPlan(e.target.value)
                setConfirm(false)
              }}
              aria-label="New plan"
            >
              {PLAN_CHOICES.map(p => (
                <option key={p.id} value={p.id}>
                  {p.label}
                </option>
              ))}
            </select>
            <button
              type="button"
              className={s.apply}
              data-live={!testMode ? "true" : undefined}
              onClick={apply}
              disabled={busy}
            >
              {testMode
                ? "Apply to sandbox"
                : confirm
                  ? `Yes, change ${picked.email}’s real plan`
                  : "Apply to the real account"}
            </button>
            {confirm ? (
              <button type="button" className={s.ghost} onClick={() => setConfirm(false)}>
                Cancel
              </button>
            ) : null}
            <button
              type="button"
              className={s.ghost}
              onClick={() => {
                setPicked(null)
                setMessage({ kind: "", text: "" })
              }}
            >
              Choose someone else
            </button>
          </div>
          {testMode ? (
            <p className={s.note}>
              <a href={`/account/?viewAs=${picked.id}`} target="_blank" rel="noreferrer">
                Open their account in test mode →
              </a>
            </p>
          ) : null}
        </section>
      )}

      {message.text ? (
        <p className={message.kind === "error" ? s.error : message.kind === "warn" ? s.warn : s.ok} role="status">
          {message.text}
        </p>
      ) : null}
    </div>
  )
}

export default RoleChanger
