import * as React from "react"
import { adminCall } from "./admin-call"
import { NAMESERVER_GUIDES } from "../../data/nameserver-guides"
import * as s from "./SitesTest.module.css"

/**
 * Try an address out before a customer depends on it — FCS-114.
 * ============================================================================
 * Three kinds of address, each with a hello-world page so a failure can only be
 * the DNS or the hosting, never a template:
 *
 *   1  a domain      (a) one already on our Cloudflare account — point it
 *                    (b) one that is not — start onboarding, show the nameservers
 *                        and how to change them at Namecheap, Squarespace, GoDaddy
 *   2  a subdomain   name.freecontractorservices.com, with the capacity gauge
 *   3  a page        freecontractorservices.com/name
 *
 * Every action shows the steps it took and how each went — see admin-sites for why.
 * The registrar instructions are the same ones customers are shown (FCS-081).
 */

const GUIDE_IDS = ["namecheap", "squarespace", "godaddy"]
const GUIDES = GUIDE_IDS.map(id => NAMESERVER_GUIDES.find(g => g.id === id)).filter(Boolean)
const APEX = "freecontractorservices.com"

const Steps = ({ steps }) =>
  steps?.length ? (
    <ul className={s.steps} data-testid="sites-steps">
      {steps.map((step, i) => (
        <li key={i} data-ok={step.ok === null ? "info" : String(step.ok)}>
          <span className={s.mark} aria-hidden="true">
            {step.ok === null ? "–" : step.ok ? "✓" : "✕"}
          </span>
          <span>
            {step.label}
            {step.detail ? <span className={s.detail}> — {step.detail}</span> : null}
          </span>
        </li>
      ))}
    </ul>
  ) : null

const Capacity = ({ capacity }) => {
  if (!capacity) return null
  const pct = Math.min(100, Math.round((capacity.used / capacity.max) * 100))
  return (
    <div className={s.capacity} data-testid="sites-capacity">
      <div className={s.capacityHead}>
        <strong>
          {capacity.used}/{capacity.max}
        </strong>
        <span>websites hosted — {capacity.customers} customers, {capacity.tests} tests</span>
      </div>
      <div className={s.bar} role="img" aria-label={`${capacity.used} of ${capacity.max} websites`}>
        <span style={{ width: `${pct}%` }} data-full={pct >= 90 ? "true" : undefined} />
      </div>
    </div>
  )
}

const Nameservers = ({ nameservers }) => {
  const [open, setOpen] = React.useState(GUIDES[0]?.id)
  const guide = GUIDES.find(g => g.id === open)
  return (
    <div className={s.ns} data-testid="sites-nameservers">
      <p className={s.lead}>
        Change the domain&apos;s nameservers at its registrar to these two. It can take a few hours (occasionally
        up to a day) to spread.
      </p>
      <ul className={s.nsList}>
        {nameservers.map(n => (
          <li key={n}>
            <code>{n}</code>
          </li>
        ))}
      </ul>
      <div className={s.tabs} role="tablist">
        {GUIDES.map(g => (
          <button key={g.id} type="button" role="tab" aria-selected={open === g.id} data-on={open === g.id ? "true" : undefined} onClick={() => setOpen(g.id)}>
            {g.name.replace(/ \(.*$/, "")}
          </button>
        ))}
      </div>
      {guide ? (
        <ol className={s.guide}>
          {guide.steps.map(step => (
            <li key={step}>{step}</li>
          ))}
        </ol>
      ) : null}
      <p className={s.fine}>Registrars rename their buttons from time to time; look for the same words.</p>
    </div>
  )
}

const SitesTest = () => {
  const [overview, setOverview] = React.useState(null)
  const [problem, setProblem] = React.useState("")
  const [busy, setBusy] = React.useState("")

  const [domain, setDomain] = React.useState("")
  const [zone, setZone] = React.useState(undefined) // undefined = not asked, null = not on Cloudflare
  const [confirm, setConfirm] = React.useState(null)
  const [domainSteps, setDomainSteps] = React.useState([])
  const [domainMsg, setDomainMsg] = React.useState("")

  const [sub, setSub] = React.useState("")
  const [subSteps, setSubSteps] = React.useState([])
  const [subMsg, setSubMsg] = React.useState("")
  const [page, setPage] = React.useState("")
  const [pageSteps, setPageSteps] = React.useState([])
  const [pageMsg, setPageMsg] = React.useState("")

  const load = React.useCallback(async () => {
    const res = await adminCall("admin-sites", { action: "overview" })
    if (!res.ok) {
      setProblem(res.body.message || `Could not load this (HTTP ${res.status}).`)
      return
    }
    setProblem("")
    setOverview(res.body)
  }, [])

  React.useEffect(() => {
    load()
  }, [load])

  /** One call, with its result folded into the screen. */
  const run = async (name, body, onDone) => {
    setBusy(name)
    const res = await adminCall("admin-sites", body)
    setBusy("")
    onDone(res)
    if (res.ok || res.body?.steps) load()
  }

  const asked = domain.trim().toLowerCase()
  const lookup = () => {
    setDomainSteps([])
    setDomainMsg("")
    setConfirm(null)
    run("lookup", { action: "domain-lookup", domain: asked }, res => {
      if (!res.ok) return setDomainMsg(res.body.message || "That did not work.")
      setZone(res.body.zone)
      if (res.body.domain) setDomain(res.body.domain)
    })
  }
  const onboard = () =>
    run("onboard", { action: "domain-onboard", domain: asked }, res => {
      setDomainSteps(res.body.steps || [])
      if (!res.ok) return setDomainMsg(res.body.message || "")
      setDomainMsg("")
      setZone(res.body.zone)
    })
  const connect = replace =>
    run("connect", { action: "domain-connect", domain: asked, replace, real: true }, res => {
      setDomainSteps(res.body.steps || [])
      setDomainMsg(res.ok ? "" : res.body.message || "")
      setConfirm(res.ok && res.body.needsConfirm ? res.body.existing : null)
    })

  const createSub = () =>
    run("sub", { action: "create-subdomain", name: sub, real: true }, res => {
      setSubSteps(res.body.steps || [])
      setSubMsg(res.ok ? "" : res.body.message || "")
    })
  const createPage = () =>
    run("page", { action: "create-path", name: page }, res => {
      setPageSteps(res.body.steps || [])
      setPageMsg(res.ok ? "" : res.body.message || "")
    })
  const remove = id => run(`rm-${id}`, { action: "remove", id }, () => {})

  const tests = overview?.tests || []
  const full = overview && overview.capacity.used >= overview.capacity.max

  return (
    <div className={s.wrap} data-testid="sites-test">
      <h2 className={s.h2}>Test addresses</h2>
      <p className={s.lead}>
        Make a hello-world page at each kind of address to prove the DNS and hosting work. Nothing here touches a
        customer&apos;s website.
      </p>
      {problem ? <p className={s.error}>{problem}</p> : null}
      {overview && !overview.cloudflare.configured ? (
        <p className={s.error}>Cloudflare is not connected on this environment, so the domain tests cannot run.</p>
      ) : null}

      <Capacity capacity={overview?.capacity} />

      {/* ── 1. a domain ── */}
      <section className={s.card}>
        <h3 className={s.h3}>1 · A domain</h3>
        <p className={s.lead}>
          Check whether it is already on our Cloudflare account. If it is, point it at a hello-world page; if not,
          start onboarding.
        </p>
        <div className={s.row}>
          <input
            className={s.input}
            aria-label="Domain"
            placeholder="acme.com"
            value={domain}
            onChange={e => {
              setDomain(e.target.value)
              setZone(undefined)
              setConfirm(null)
            }}
            onKeyDown={e => e.key === "Enter" && asked && lookup()}
          />
          <button type="button" className={s.button} disabled={!asked || busy === "lookup"} onClick={lookup}>
            {busy === "lookup" ? "Checking…" : "Check this domain"}
          </button>
        </div>

        {zone === null ? (
          <div className={s.result} data-testid="sites-domain-new">
            <p>
              <strong>{asked}</strong> is not on our Cloudflare account (1b).
            </p>
            <button type="button" className={s.button} disabled={busy === "onboard"} onClick={onboard}>
              {busy === "onboard" ? "Starting…" : "Start onboarding"}
            </button>
          </div>
        ) : null}

        {zone && zone.status !== "active" ? (
          <div className={s.result} data-testid="sites-domain-pending">
            <p>
              <strong>{asked}</strong> is on Cloudflare, waiting for its nameservers to be changed ({zone.status}).
            </p>
            <Nameservers nameservers={zone.nameservers} />
            <button type="button" className={s.button} disabled={busy === "lookup"} onClick={lookup}>
              Check again
            </button>
          </div>
        ) : null}

        {zone && zone.status === "active" ? (
          <div className={s.result} data-testid="sites-domain-active">
            <p>
              <strong>{asked}</strong> is on our Cloudflare account and active (1a).
            </p>
            {confirm ? (
              <div className={s.warn} data-testid="sites-confirm">
                <p>
                  These records already exist and would be replaced. If this is a live site, it will stop pointing where
                  it does now.
                </p>
                <ul>
                  {confirm.map((r, i) => (
                    <li key={i}>
                      <code>
                        {r.type} {r.name} → {r.content}
                      </code>
                    </li>
                  ))}
                </ul>
                <button type="button" className={s.button} disabled={busy === "connect"} onClick={() => connect(true)}>
                  Replace them and connect
                </button>
              </div>
            ) : (
              <button type="button" className={s.button} disabled={busy === "connect" || full} onClick={() => connect(false)}>
                {busy === "connect" ? "Connecting…" : "Point it at a hello-world page"}
              </button>
            )}
          </div>
        ) : null}

        {domainMsg ? <p className={s.error}>{domainMsg}</p> : null}
        <Steps steps={domainSteps} />
      </section>

      {/* ── 2. a subdomain ── */}
      <section className={s.card}>
        <h3 className={s.h3}>2 · A subdomain</h3>
        <div className={s.row}>
          <span className={s.affixed}>
            <input
              className={s.input}
              aria-label="Subdomain"
              placeholder="acme"
              value={sub}
              onChange={e => setSub(e.target.value.toLowerCase())}
              onKeyDown={e => e.key === "Enter" && sub && createSub()}
            />
            <span className={s.suffix}>.{APEX}</span>
          </span>
          <button type="button" className={s.button} disabled={!sub || busy === "sub" || full} onClick={createSub}>
            {busy === "sub" ? "Creating…" : "Create test site"}
          </button>
        </div>
        <p className={s.lead}>
          This makes a real GitHub repository and a real DNS record for the name, the same as a paying customer gets. Remove (below)
          deletes both again.
        </p>
        {full ? <p className={s.error}>The host is full. Remove a test or raise the capacity.</p> : null}
        {subMsg ? <p className={s.error}>{subMsg}</p> : null}
        <Steps steps={subSteps} />
      </section>

      {/* ── 3. a page on the main address ── */}
      <section className={s.card}>
        <h3 className={s.h3}>3 · A page on the main address</h3>
        <div className={s.row}>
          <span className={s.affixed}>
            <span className={s.prefix}>{APEX}/</span>
            <input
              className={s.input}
              aria-label="Page name"
              placeholder="acme"
              value={page}
              onChange={e => setPage(e.target.value.toLowerCase())}
              onKeyDown={e => e.key === "Enter" && page && createPage()}
            />
          </span>
          <button type="button" className={s.button} disabled={!page || busy === "page"} onClick={createPage}>
            {busy === "page" ? "Creating…" : "Create test page"}
          </button>
        </div>
        {pageMsg ? <p className={s.error}>{pageMsg}</p> : null}
        <Steps steps={pageSteps} />
      </section>

      {/* ── what has been made ── */}
      <section className={s.card}>
        <h3 className={s.h3}>Test pages made</h3>
        {tests.length === 0 ? (
          <p className={s.lead}>None yet.</p>
        ) : (
          <ul className={s.tests} data-testid="sites-list">
            {tests.map(t => (
              <li key={t.id}>
                <span className={s.kind}>{t.kind}</span>
                <a href={t.url} target="_blank" rel="noreferrer">
                  {t.url.replace(/^https:\/\//, "")}
                </a>
                <button type="button" className={s.link} disabled={busy === `rm-${t.id}`} onClick={() => remove(t.id)}>
                  {busy === `rm-${t.id}` ? "Removing…" : "Remove"}
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  )
}

export default SitesTest
