import * as React from "react"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { supabase } from "../../lib/supabase"
import * as s from "./AdminSettings.module.css"

/**
 * Settings an administrator changes — FCS-094.
 * ============================================================================
 * Today: the free-domain offer. A switch, and the price under which a domain
 * is offered free on sign-up.
 *
 * ── THE SWITCH IS THE WHOLE OFFER ──────────────────────────────────────────
 * Off, every "FREE" label disappears from the domain screens, the sign-up
 * upsell stops promising a credit, and the credit notice leaves the account
 * menu. The page says so next to the switch, because a toggle that quietly
 * changes what customers are promised should say what it changes.
 *
 * ── THE PRICE IS TYPED IN DOLLARS, STORED IN CENTS ─────────────────────────
 * Nobody thinks in cents, and nobody should have to type 1400. It is
 * converted once, here, and a value that is not a clean amount is refused
 * rather than rounded into something nobody chose.
 *
 * ── SAVES ON BLUR, AND PUTS THE OLD VALUE BACK ON FAILURE ──────────────────
 * Same rules as the limits grid: never show a number the database does not
 * hold.
 */

const call = async body => {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token

  const res = await fetch(apiUrl("admin-settings"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
    },
    body: JSON.stringify(body),
  })
  return { ok: res.ok, status: res.status, body: await res.json().catch(() => ({})) }
}

const dollars = cents => (cents / 100).toFixed(2)
const usd = cents =>
  new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(cents / 100)

const AdminSettings = () => {
  const [offer, setOffer] = React.useState(null)
  const [fixed, setFixed] = React.useState({ min: 0, credit: 0 })
  const [price, setPrice] = React.useState("")
  const [error, setError] = React.useState("")
  const [denied, setDenied] = React.useState("")
  const [saved, setSaved] = React.useState("")
  const [busy, setBusy] = React.useState(false)

  React.useEffect(() => {
    let alive = true
    call({ action: "get" }).then(res => {
      if (!alive) return
      if (res.status === 401) return setDenied("Log in with an administrator account to see the settings.")
      if (res.status === 403) return setDenied("This account is not an administrator, so the settings are not shown here.")
      if (!res.ok) return setError(res.body.message || `Could not load the settings (HTTP ${res.status}).`)
      setOffer(res.body.domainOffer)
      setPrice(dollars(res.body.domainOffer.freeBelowCents))
      setFixed({ min: res.body.domainMinCents, credit: res.body.domainCreditCents })
    })
    return () => {
      alive = false
    }
  }, [])

  const flash = what => {
    setSaved(what)
    setTimeout(() => setSaved(v => (v === what ? "" : v)), 1600)
  }

  const save = async (patch, what) => {
    setBusy(true)
    setError("")
    const before = offer
    setOffer({ ...offer, ...patch })
    const res = await call({ action: "set", domainOffer: patch })
    setBusy(false)
    if (!res.ok) {
      // Back to what the database holds.
      setOffer(before)
      setPrice(dollars(before.freeBelowCents))
      setError(res.body.message || "That did not save.")
      return
    }
    setOffer(res.body.domainOffer)
    setPrice(dollars(res.body.domainOffer.freeBelowCents))
    flash(what)
  }

  const commitPrice = () => {
    const text = price.trim().replace(/^\$/, "")
    if (!/^\d{1,4}(\.\d{1,2})?$/.test(text)) {
      setError("Enter an amount in dollars, such as 14.00.")
      setPrice(dollars(offer.freeBelowCents))
      return
    }
    const cents = Math.round(Number(text) * 100)
    if (cents === offer.freeBelowCents) return
    save({ freeBelowCents: cents }, "price")
  }

  if (denied) return <p className={s.note}>{denied}</p>
  if (error && !offer) return <p className={s.error}>{error}</p>
  if (!offer) return <p className={s.note}>Loading the settings…</p>

  return (
    <div>
      <h2 className={s.title}>Free domain offer</h2>
      <p className={s.note}>
        Domains whose wholesale price is under the amount below are offered free on sign-up. Every
        domain is sold for at least {usd(fixed.min)}, whatever the registrar charges.
      </p>

      {error ? <p className={s.error}>{error}</p> : null}

      <div className={s.row}>
        <div className={s.rowText}>
          <span className={s.label}>The offer</span>
          <span className={s.help}>
            {offer.enabled
              ? "On. Free domains are labelled, and the sign-up upsell and the credit notice are shown."
              : "Off. Nothing is labelled free, the upsell promises no credit, and the credit notice is hidden."}
          </span>
        </div>
        <button
          type="button"
          role="switch"
          aria-checked={offer.enabled}
          aria-label="Free domain offer"
          className={s.toggle}
          data-on={offer.enabled ? "true" : undefined}
          disabled={busy}
          onClick={() => save({ enabled: !offer.enabled }, "switch")}
        >
          <span className={s.knob} />
        </button>
        <span className={s.saved} data-show={saved === "switch" ? "true" : undefined}>Saved</span>
      </div>

      <div className={s.row}>
        <div className={s.rowText}>
          <label className={s.label} htmlFor="free-below">Free below</label>
          <span className={s.help}>
            A domain costing us less than this is free. Currently {usd(offer.freeBelowCents)}.
            Changes save when you leave the box.
          </span>
        </div>
        <span className={s.money}>
          <span aria-hidden="true">$</span>
          <input
            id="free-below"
            className={s.input}
            inputMode="decimal"
            value={price}
            onChange={e => setPrice(e.target.value)}
            onBlur={commitPrice}
            onKeyDown={e => {
              if (e.key === "Enter") e.currentTarget.blur()
            }}
            disabled={busy}
          />
        </span>
        <span className={s.saved} data-show={saved === "price" ? "true" : undefined}>Saved</span>
      </div>

      <p className={s.note}>
        The first-domain credit is {usd(fixed.credit)}. That and the {usd(fixed.min)} minimum are
        set in the project file, not here, because they change what every customer is charged.
      </p>
    </div>
  )
}

export default AdminSettings
